;insert into REP.DIM_CURRENCY_FTP ( ENTITY_CODE, CURRENCY_FTP_CODE, CURRENCY_FTP_DESC ) select STG.T_CURRENCY_FTP_V.ENTITY_CODE, STG.T_CURRENCY_FTP_V.CURRENCY_FTP_CODE, STG.T_CURRENCY_FTP_V.CURRENCY_FTP_DESC from STG.T_CURRENCY_FTP_V left join REP.DIM_CURRENCY_FTP on STG.T_CURRENCY_FTP_V.ENTITY_CODE=REP.DIM_CURRENCY_FTP.ENTITY_CODE and STG.T_CURRENCY_FTP_V.CURRENCY_FTP_CODE = REP.DIM_CURRENCY_FTP.CURRENCY_FTP_CODE where REP.DIM_CURRENCY_FTP.ENTITY_CODE is null and REP.DIM_CURRENCY_FTP.CURRENCY_FTP_CODE is null 
;update REP.DIM_COMMISSION_TYPE set REP.DIM_COMMISSION_TYPE.COMMISSION_TYPE_DESC=STG.T_COMMISSION_TYPE_V.COMMISSION_TYPE_DESC from REP.DIM_COMMISSION_TYPE inner join STG.T_COMMISSION_TYPE_V on STG.T_COMMISSION_TYPE_V.ENTITY_CODE = REP.DIM_COMMISSION_TYPE.ENTITY_CODE and STG.T_COMMISSION_TYPE_V.COMMISSION_TYPE_CODE = REP.DIM_COMMISSION_TYPE.COMMISSION_TYPE_CODE
;insert into REP.DIM_COMMISSION_TYPE ( ENTITY_CODE, COMMISSION_TYPE_CODE, COMMISSION_TYPE_DESC ) select STG.T_COMMISSION_TYPE_V.ENTITY_CODE, STG.T_COMMISSION_TYPE_V.COMMISSION_TYPE_CODE, STG.T_COMMISSION_TYPE_V.COMMISSION_TYPE_DESC from STG.T_COMMISSION_TYPE_V left join REP.DIM_COMMISSION_TYPE on STG.T_COMMISSION_TYPE_V.ENTITY_CODE=REP.DIM_COMMISSION_TYPE.ENTITY_CODE and STG.T_COMMISSION_TYPE_V.COMMISSION_TYPE_CODE = REP.DIM_COMMISSION_TYPE.COMMISSION_TYPE_CODE where REP.DIM_COMMISSION_TYPE.ENTITY_CODE is null and REP.DIM_COMMISSION_TYPE.COMMISSION_TYPE_CODE is null 


--DIM_BRANCH

;update REP.DIM_BRANCH set REP.DIM_BRANCH.BRANCH_DESC=STG.T_BRANCH_V.BRANCH_DESC , REP.DIM_BRANCH.BRANCH_TYPE_CODE=STG.T_BRANCH_V.BRANCH_TYPE_CODE , REP.DIM_BRANCH.BRANCH_AREA_CODE=STG.T_BRANCH_V.BRANCH_AREA_CODE , REP.DIM_BRANCH.BRANCH_AREA_DESC=STG.T_BRANCH_V.BRANCH_AREA_DESC , REP.DIM_BRANCH.PARENT_BRANCH_CODE=STG.T_BRANCH_V.PARENT_BRANCH_CODE from REP.DIM_BRANCH inner join STG.T_BRANCH_V on STG.T_BRANCH_V.ENTITY_CODE = REP.DIM_BRANCH.ENTITY_CODE and STG.T_BRANCH_V.BRANCH_CODE = REP.DIM_BRANCH.BRANCH_CODE
;insert into REP.DIM_BRANCH ( ENTITY_CODE, BRANCH_CODE, BRANCH_DESC, BRANCH_TYPE_CODE, BRANCH_AREA_CODE, BRANCH_AREA_DESC, PARENT_BRANCH_CODE ) select STG.T_BRANCH_V.ENTITY_CODE, STG.T_BRANCH_V.BRANCH_CODE, STG.T_BRANCH_V.BRANCH_DESC, STG.T_BRANCH_V.BRANCH_TYPE_CODE, STG.T_BRANCH_V.BRANCH_AREA_CODE, STG.T_BRANCH_V.BRANCH_AREA_DESC, STG.T_BRANCH_V.PARENT_BRANCH_CODE from STG.T_BRANCH_V left join REP.DIM_BRANCH on STG.T_BRANCH_V.ENTITY_CODE=REP.DIM_BRANCH.ENTITY_CODE and STG.T_BRANCH_V.BRANCH_CODE = REP.DIM_BRANCH.BRANCH_CODE where REP.DIM_BRANCH.ENTITY_CODE is null and REP.DIM_BRANCH.BRANCH_CODE is null 

INSERT INTO REP.DIM_BRANCH_TYPE (
	  ENTITY_CODE
	, BRANCH_TYPE_CODE) 
SELECT 
	  src.ENTITY_CODE
	, src.BRANCH_TYPE_CODE 
FROM ( 
			SELECT 
					ENTITY_CODE
				, BRANCH_TYPE_CODE
			FROM REP.DIM_BRANCH 
			GROUP BY 
				  ENTITY_CODE
				, BRANCH_TYPE_CODE 
		) src 
	LEFT JOIN REP.DIM_BRANCH_TYPE min_Dim_Tbl ON src.ENTITY_CODE=min_Dim_Tbl.ENTITY_CODE AND src.BRANCH_TYPE_CODE = min_Dim_Tbl.BRANCH_TYPE_CODE 
WHERE min_Dim_Tbl.BRANCH_TYPE_CODE IS NULL

UPDATE trg
   SET 
		trg.BRANCH_TYPE_DESC = src.BRANCH_TYPE_DESC
	FROM REP.DIM_BRANCH trg 
	LEFT JOIN REP.DIM_BRANCH_TYPE src
	ON	trg.ENTITY_CODE = src.ENTITY_CODE
		AND trg.BRANCH_TYPE_CODE = src.BRANCH_TYPE_CODE;


UPDATE trg
   SET 
		trg.PARENT_BRANCH_DESC = src.BRANCH_DESC,
		trg.PARENT_BRANCH_AREA_CODE = src.BRANCH_AREA_CODE,
		trg.PARENT_BRANCH_AREA_DESC = src.BRANCH_AREA_DESC,
		trg.PARENT_BRANCH_TYPE_CODE = src.BRANCH_TYPE_CODE,
		trg.PARENT_BRANCH_TYPE_DESC = src.BRANCH_TYPE_DESC
	FROM REP.DIM_BRANCH trg 
	LEFT JOIN REP.DIM_BRANCH src
	ON	trg.ENTITY_CODE = src.ENTITY_CODE
		AND trg.PARENT_BRANCH_CODE = src.BRANCH_CODE;




--DIM_COUNTRY

update CLS.CLS_COUNTRY set CLS.CLS_COUNTRY.COUNTRY_ISO=STG.C_COUNTRY_V.COUNTRY_ISO, CLS.CLS_COUNTRY.COUNTRY_NAME = STG.C_COUNTRY_V.COUNTRY_NAME from CLS.CLS_COUNTRY inner join STG.C_COUNTRY_V on STG.C_COUNTRY_V.COUNTRY_CODE = CLS.CLS_COUNTRY.COUNTRY_CODE /*and STG.C_COUNTRY_V.COUNTRY_NAME = CLS.CLS_COUNTRY.COUNTRY_NAME*/
