UPDATE REP.DIM_COUNTRY SET
		REP.DIM_COUNTRY.COUNTRY_NAME=CLS.CLS_COUNTRY.COUNTRY_NAME
	,	REP.DIM_COUNTRY.COUNTRY_ISO=CLS.CLS_COUNTRY.COUNTRY_ISO
FROM CLS.CLS_COUNTRY
	INNER JOIN REP.DIM_COUNTRY ON CLS.CLS_COUNTRY.COUNTRY_CODE = REP.DIM_COUNTRY.COUNTRY_CODE;

INSERT INTO REP.DIM_COUNTRY ( 
		COUNTRY_CODE
	,	COUNTRY_NAME
	,	COUNTRY_ISO
) 
SELECT 
		CLS.CLS_COUNTRY.COUNTRY_CODE
	,	CLS.CLS_COUNTRY.COUNTRY_NAME
	,	CLS.CLS_COUNTRY.COUNTRY_ISO
FROM CLS.CLS_COUNTRY 
	LEFT JOIN REP.DIM_COUNTRY ON CLS.CLS_COUNTRY.COUNTRY_CODE=REP.DIM_COUNTRY.COUNTRY_CODE 
WHERE REP.DIM_COUNTRY.COUNTRY_CODE IS NULL;




