--DIM_ENTITY

update CLS.CLS_ENTITY_TYPE set CLS.CLS_ENTITY_TYPE.ENTITY_TYPE_DESC=STG.C_ENTITY_TYPE_V.ENTITY_TYPE_DESC from CLS.CLS_ENTITY_TYPE inner join STG.C_ENTITY_TYPE_V on STG.C_ENTITY_TYPE_V.ENTITY_TYPE_CODE = CLS.CLS_ENTITY_TYPE.ENTITY_TYPE_CODE
insert into CLS.CLS_ENTITY_TYPE ( ENTITY_TYPE_CODE, ENTITY_TYPE_DESC ) select STG.C_ENTITY_TYPE_V.ENTITY_TYPE_CODE, STG.C_ENTITY_TYPE_V.ENTITY_TYPE_DESC from STG.C_ENTITY_TYPE_V left join CLS.CLS_ENTITY_TYPE on STG.C_ENTITY_TYPE_V.ENTITY_TYPE_CODE=CLS.CLS_ENTITY_TYPE.ENTITY_TYPE_CODE where CLS.CLS_ENTITY_TYPE.ENTITY_TYPE_CODE is null 

update CLS.CLS_SECURITIZATION set CLS.CLS_SECURITIZATION.SECURITIZATION_DESC=STG.C_SECURITIZATION_V.SECURITIZATION_DESC from CLS.CLS_SECURITIZATION inner join STG.C_SECURITIZATION_V on STG.C_SECURITIZATION_V.SECURITIZATION_CODE = CLS.CLS_SECURITIZATION.SECURITIZATION_CODE
insert into CLS.CLS_SECURITIZATION ( SECURITIZATION_CODE, SECURITIZATION_DESC ) select STG.C_SECURITIZATION_V.SECURITIZATION_CODE, STG.C_SECURITIZATION_V.SECURITIZATION_DESC from STG.C_SECURITIZATION_V left join CLS.CLS_SECURITIZATION on STG.C_SECURITIZATION_V.SECURITIZATION_CODE=CLS.CLS_SECURITIZATION.SECURITIZATION_CODE where CLS.CLS_SECURITIZATION.SECURITIZATION_CODE is null 

update CLS.CLS_ENTITY set CLS.CLS_ENTITY.ENTITY_NAME=STG.C_ENTITY_V.ENTITY_NAME , CLS.CLS_ENTITY.COUNTRY_CODE=STG.C_ENTITY_V.COUNTRY_CODE , CLS.CLS_ENTITY.SECURITIZATION_CODE=STG.C_ENTITY_V.SECURITIZATION_CODE , CLS.CLS_ENTITY.ENTITY_TYPE_CODE=STG.C_ENTITY_V.ENTITY_TYPE_CODE from CLS.CLS_ENTITY inner join STG.C_ENTITY_V on STG.C_ENTITY_V.ENTITY_CODE = CLS.CLS_ENTITY.ENTITY_CODE
insert into CLS.CLS_ENTITY ( ENTITY_CODE, ENTITY_NAME, COUNTRY_CODE, SECURITIZATION_CODE, ENTITY_TYPE_CODE ) select STG.C_ENTITY_V.ENTITY_CODE, STG.C_ENTITY_V.ENTITY_NAME, STG.C_ENTITY_V.COUNTRY_CODE, STG.C_ENTITY_V.SECURITIZATION_CODE, STG.C_ENTITY_V.ENTITY_TYPE_CODE from STG.C_ENTITY_V left join CLS.CLS_ENTITY on STG.C_ENTITY_V.ENTITY_CODE=CLS.CLS_ENTITY.ENTITY_CODE where CLS.CLS_ENTITY.ENTITY_CODE is null 

UPDATE REP.DIM_ENTITY SET 
	  REP.DIM_ENTITY.ENTITY_NAME=CLS.CLS_ENTITY.ENTITY_NAME 
	, REP.DIM_ENTITY.ENTITY_COUNTRY_CODE=CLS.CLS_ENTITY.COUNTRY_CODE 
	, REP.DIM_ENTITY.ENTITY_COUNTRY_NAME=CLS.CLS_COUNTRY.COUNTRY_NAME 
	, REP.DIM_ENTITY.ENTITY_COUNTRY_ISO=CLS.CLS_COUNTRY.COUNTRY_ISO 
	, REP.DIM_ENTITY.ENTITY_TYPE_CODE=CLS.CLS_ENTITY.ENTITY_TYPE_CODE
	, REP.DIM_ENTITY.ENTITY_TYPE_DESC =CLS.CLS_ENTITY_TYPE.ENTITY_TYPE_DESC
	, REP.DIM_ENTITY.ENTITY_SECURITIZATION_CODE=CLS.CLS_ENTITY.SECURITIZATION_CODE
	, REP.DIM_ENTITY.ENTITY_SECURITIZATION_DESC=CLS.CLS_SECURITIZATION.SECURITIZATION_DESC
FROM CLS.CLS_ENTITY
	INNER JOIN REP.DIM_ENTITY ON CLS.CLS_ENTITY.ENTITY_CODE = REP.DIM_ENTITY.ENTITY_CODE
	LEFT JOIN CLS.CLS_COUNTRY ON CLS.CLS_COUNTRY.COUNTRY_CODE= CLS.CLS_ENTITY.COUNTRY_CODE
	LEFT JOIN CLS.CLS_ENTITY_TYPE ON CLS.CLS_ENTITY_TYPE.ENTITY_TYPE_CODE = CLS.CLS_ENTITY.ENTITY_TYPE_CODE
	LEFT JOIN CLS.CLS_SECURITIZATION ON CLS_SECURITIZATION.SECURITIZATION_CODE = CLS.CLS_ENTITY.SECURITIZATION_CODE;

INSERT INTO REP.DIM_ENTITY(
	  ENTITY_CODE
	, ENTITY_NAME
	, ENTITY_COUNTRY_CODE
	, ENTITY_COUNTRY_NAME
	, ENTITY_COUNTRY_ISO
	, ENTITY_TYPE_CODE
	, ENTITY_TYPE_DESC
	, ENTITY_SECURITIZATION_CODE
	, ENTITY_SECURITIZATION_DESC
) 
SELECT 
		CLS.CLS_ENTITY.ENTITY_CODE 
	,	CLS.CLS_ENTITY.ENTITY_NAME
	,	CLS.CLS_COUNTRY.COUNTRY_CODE
	,	CLS.CLS_COUNTRY.COUNTRY_NAME
	,	CLS.CLS_COUNTRY.COUNTRY_ISO
	,	CLS.CLS_ENTITY_TYPE.ENTITY_TYPE_CODE
	,	CLS.CLS_ENTITY_TYPE.ENTITY_TYPE_DESC
	,	CLS.CLS_SECURITIZATION.SECURITIZATION_CODE
	,	CLS.CLS_SECURITIZATION.SECURITIZATION_DESC
FROM CLS.CLS_ENTITY
	LEFT JOIN REP.DIM_ENTITY ON CLS.CLS_ENTITY.ENTITY_CODE= REP.DIM_ENTITY.ENTITY_CODE
	LEFT JOIN CLS.CLS_COUNTRY ON CLS.CLS_ENTITY.COUNTRY_CODE = CLS.CLS_COUNTRY.COUNTRY_CODE
